/** Insert a read-only selected-PC gate after actual object/attack decoding, before original skill code resumes. */
public final class SelectedPlayerIntentMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",F=P+"ForcedCombat",I=F+"$Intent",H=P+"NativeSelectedPlayerIntent";
 static void authority(ClassNode c){if(c.methods.stream().anyMatch(m->m.name.equals("nativeSelectedObjectIntent")))throw new AssertionError("fresh reader only");var m=new MethodNode(ACC_STATIC,"nativeSelectedObjectIntent","(L"+PC+";J)Z",null,null);var no=new LabelNode();m.instructions.add(new FieldInsnNode(GETSTATIC,F,"CURRENT","Ljava/lang/ThreadLocal;"));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,"java/lang/ThreadLocal","get","()Ljava/lang/Object;",false));m.instructions.add(new TypeInsnNode(CHECKCAST,I));m.instructions.add(new VarInsnNode(ASTORE,3));m.instructions.add(new VarInsnNode(ALOAD,3));m.instructions.add(new JumpInsnNode(IFNULL,no));m.instructions.add(new VarInsnNode(ALOAD,3));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,I,"attacker","()L"+PC+";",false));m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new JumpInsnNode(IF_ACMPNE,no));m.instructions.add(new VarInsnNode(ALOAD,3));m.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,I,"target","()J",false));m.instructions.add(new VarInsnNode(LLOAD,1));m.instructions.add(new InsnNode(LCMP));m.instructions.add(new JumpInsnNode(IFNE,no));m.instructions.add(new InsnNode(ICONST_1));m.instructions.add(new InsnNode(IRETURN));m.instructions.add(no);m.instructions.add(new FrameNode(F_APPEND,1,new Object[]{I},0,null));m.instructions.add(new InsnNode(ICONST_0));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);}
 static List<String> patch(ClassNode c){if(c.name.equals(F)){authority(c);return List.of();}var ports=new ArrayList<String>();
  for(var m:c.methods){if((m.access&ACC_STATIC)!=0||!(m.desc.startsWith("([B")||m.desc.startsWith("(L"+P+"Protocol$AttackSpellRequest;")||m.desc.startsWith("(L"+P+"Protocol$ObjectSpellRequest;"))||!m.desc.endsWith(")V")||!m.desc.contains(P+"BattleSpellCatalog$")||!(m.name.startsWith("use")||m.name.startsWith("native")))continue;boolean changed=false;
   if(m.desc.startsWith("(L"+P+"Protocol$AttackSpellRequest;")||m.desc.startsWith("(L"+P+"Protocol$ObjectSpellRequest;")){String record=m.desc.startsWith("(L"+P+"Protocol$AttackSpellRequest;")?"AttackSpellRequest":"ObjectSpellRequest";var x=new InsnList();var ok=new LabelNode();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,H,record.equals("ObjectSpellRequest")?"object":"attack","(L"+PC+";L"+P+"Protocol$"+record+";)Z",false));x.add(new JumpInsnNode(IFNE,ok));x.add(new InsnNode(RETURN));x.add(ok);m.instructions.insert(x);ports.add(m.name+"\t"+m.desc+"\tdecoded-argument\t1");changed=true;}

   for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(P+"Protocol")&&Set.of("objectSpellRequest","attackSpellRequest").contains(call.name)){
    var next=FreezeAcceptedMethods.next(call);if(!(next instanceof VarInsnNode store)||store.getOpcode()!=ASTORE){boolean delegated=false;var cursor=next;for(int step=0;cursor!=null&&step<10;step++,cursor=FreezeAcceptedMethods.next(cursor)){if(cursor instanceof MethodInsnNode target){String record=call.name.equals("objectSpellRequest")?"ObjectSpellRequest":"AttackSpellRequest";delegated=target.owner.equals(PC)&&target.desc.startsWith("(L"+P+"Protocol$"+record+";")&&target.desc.endsWith(")V")&&target.desc.contains(P+"BattleSpellCatalog$")&&c.methods.stream().anyMatch(v->v.name.equals(target.name)&&v.desc.equals(target.desc));break;}if(cursor.getOpcode()==PUTFIELD||cursor.getOpcode()==PUTSTATIC||cursor instanceof JumpInsnNode)break;}if(delegated)continue;throw new AssertionError("review parser result "+m.name);}
    for(var before=m.instructions.getFirst();before!=n;before=before.getNext())if(before instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&Set.of("playerHp","playerMp").contains(f.name)||before instanceof MethodInsnNode a&&Set.of("admit","commitSpellReady","saveEconomy","commit").contains(a.name))throw new AssertionError("parser gate must precede cost "+m.name);
    String record=call.name.equals("objectSpellRequest")?"ObjectSpellRequest":"AttackSpellRequest";var x=new InsnList();var ok=new LabelNode();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,store.var));x.add(new MethodInsnNode(INVOKESTATIC,H,record.equals("ObjectSpellRequest")?"object":"attack","(L"+PC+";L"+P+"Protocol$"+record+";)Z",false));x.add(new JumpInsnNode(IFNE,ok));x.add(new InsnNode(RETURN));x.add(ok);m.instructions.insert(store,x);ports.add(m.name+"\t"+m.desc+"\t"+call.name+"\t"+store.var);changed=true;
   }
   if(changed){var single=new ClassNode();single.version=c.version;single.access=c.access;single.name=c.name;single.superName=c.superName;single.interfaces=c.interfaces;single.methods.add(m);var computed=new ClassNode();new ClassReader(FreezeAcceptedMethods.bytes(single,true)).accept(computed,ClassReader.EXPAND_FRAMES);c.methods.set(c.methods.indexOf(m),computed.methods.get(0));}
  }
  return ports;
 }
 public static void main(String[]a)throws Exception{var urls=new ArrayList<URL>();urls.add(Path.of(a[1]).toUri().toURL());try(var files=Files.list(Path.of(a[3]))){for(var p:files.filter(p->p.toString().endsWith(".jar")).sorted().toList())urls.add(p.toUri().toURL());}try(var loader=new URLClassLoader(urls.toArray(URL[]::new),ClassLoader.getPlatformClassLoader());var jar=new JarFile(a[1])){FreezeAcceptedMethods.hierarchy=loader;var ports=new ArrayList<String>();for(String name:List.of(PC,F)){var c=FreezeAcceptedMethods.read(jar,name);ports.addAll(patch(c));byte[] bytes=FreezeAcceptedMethods.bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var candidate=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(candidate,name),false)))throw new AssertionError(name);}}if(ports.isEmpty())throw new AssertionError();if(a.length>4)Files.write(Path.of(a[4]),ports);System.out.println("PASS selected-PC parser ports="+ports.size()+"; exact existing intent reader, no new authority/TLS");}}
}
